INSERT INTO legal_referentials (id, workspace_id, legal_domain, referential_type, entry_key, value_json, label, country, is_system, is_active, source_ref, description, updated_at, updated_by)
VALUES ('f1d38000-0000-0000-0000-000000001000', NULL, 'DROIT_DU_TRAVAIL', 'CONVENTION_BAREMES', 'IDCC_1000', '{"congesLegauxJours":25,"congesSupp":[],"primes":[]}', 'Cabinets d''avocats (IDCC 1000)', 'FRANCE', true, true, 'IDCC 1000 — Légifrance / kali-data', 'Barème d''ancienneté de la convention collective des cabinets d''avocats (IDCC 1000). Référence utilisée par l''outil Ancienneté pour calculer les droits conventionnels du salarié — congés légaux (25 jours base FR), congés supplémentaires d''ancienneté et prime d''ancienneté quand documentés par la CCN — puis comparer automatiquement à son contrat individuel. À enrichir si l''accord de branche prévoit des congés supplémentaires ou une prime d''ancienneté spécifique.', NOW(), NULL);

INSERT INTO legal_referentials (id, workspace_id, legal_domain, referential_type, entry_key, value_json, label, country, is_system, is_active, source_ref, description, updated_at, updated_by)
VALUES ('f1d38000-0000-0000-0000-000000001619', NULL, 'DROIT_DU_TRAVAIL', 'CONVENTION_BAREMES', 'IDCC_1619', '{"congesLegauxJours":25,"congesSupp":[],"primes":[]}', 'Cabinets dentaires (IDCC 1619)', 'FRANCE', true, true, 'IDCC 1619 — Légifrance / kali-data', 'Barème d''ancienneté de la convention collective des cabinets dentaires (IDCC 1619). Utilisé par l''outil Ancienneté pour calculer les droits conventionnels (congés légaux + ancienneté) du salarié et les comparer au contrat. Enrichir si la CCN prévoit des congés supplémentaires.', NOW(), NULL);

