INSERT INTO legal_referentials (id, workspace_id, legal_domain, referential_type, entry_key, value_json, label, country, is_system, is_active, source_ref, description, updated_at, updated_by)
VALUES ('f1d38200-0000-0000-0000-000000001597', NULL, 'DROIT_DU_TRAVAIL', 'CONVENTION_PREAVIS', 'IDCC_1597', '{"fonctions":{"OUVRIER":[{"min":0,"max":3,"mois":0},{"min":3,"max":6,"mois":1},{"min":6,"max":24,"mois":1},{"min":24,"max":null,"mois":2}],"EMPLOYE":[{"min":0,"max":6,"mois":1},{"min":6,"max":24,"mois":2},{"min":24,"max":null,"mois":2}],"AGENT_MAITRISE":[{"min":0,"max":24,"mois":2},{"min":24,"max":null,"mois":3}],"CADRE":[{"min":0,"max":null,"mois":3}]},"article":"CCN Bâtiment Ouvriers art. 9.1 / 10.1"}', 'CCN Bâtiment Ouvriers > 10 sal. (IDCC 1597) — durée de préavis', 'FR', true, true, 'CCN Bâtiment Ouvriers IDCC 1597 art. 9.1 (préavis ouvriers) / art. 10.1 (préavis cadres)', 'Durée du préavis prévue par la convention collective des ouvriers du bâtiment (IDCC 1597, entreprises occupant plus de 10 salariés) selon la catégorie professionnelle (ouvrier, employé, agent de maîtrise, cadre) et l''ancienneté en mois. Reproduit la durée légale L.1234-1 pour les ouvriers et employés ; le préavis cadre est fixé à 3 mois dès l''embauche (plus favorable). Utilisé par F-DT-25 (calculateur indemnité compensatrice de préavis). Modifier la matrice si l''avenant CCN évolue.', NOW(), NULL);

INSERT INTO legal_referentials (id, workspace_id, legal_domain, referential_type, entry_key, value_json, label, country, is_system, is_active, source_ref, description, updated_at, updated_by)
VALUES ('f1d38200-0000-0000-0000-000000002609', NULL, 'DROIT_DU_TRAVAIL', 'CONVENTION_PREAVIS', 'IDCC_2609', '{"fonctions":{"OUVRIER":[{"min":0,"max":6,"mois":1},{"min":6,"max":24,"mois":1},{"min":24,"max":null,"mois":2}],"EMPLOYE":[{"min":0,"max":6,"mois":1},{"min":6,"max":24,"mois":2},{"min":24,"max":null,"mois":2}],"AGENT_MAITRISE":[{"min":0,"max":24,"mois":2},{"min":24,"max":null,"mois":3}],"CADRE":[{"min":0,"max":null,"mois":3}]},"article":"CCN Bâtiment ETAM art. 5"}', 'CCN Bâtiment ETAM (IDCC 2609) — durée de préavis', 'FR', true, true, 'CCN Bâtiment ETAM IDCC 2609 art. 5', 'Durée du préavis prévue par la convention collective des ETAM du bâtiment (IDCC 2609) selon la catégorie professionnelle (employé, agent de maîtrise) et l''ancienneté. Le préavis ETAM est aligné sur la durée légale L.1234-1 (1 mois < 6 mois, 2 mois ≥ 6 mois) ; le préavis agent de maîtrise atteint 3 mois après 2 ans d''ancienneté. Utilisé par F-DT-25 (calculateur indemnité compensatrice de préavis). Modifier la matrice si l''avenant CCN évolue.', NOW(), NULL);

INSERT INTO legal_referentials (id, workspace_id, legal_domain, referential_type, entry_key, value_json, label, country, is_system, is_active, source_ref, description, updated_at, updated_by)
VALUES ('f1d38200-0000-0000-0000-000000001702', NULL, 'DROIT_DU_TRAVAIL', 'CONVENTION_PREAVIS', 'IDCC_1702', '{"fonctions":{"OUVRIER":[{"min":0,"max":3,"mois":0},{"min":3,"max":6,"mois":1},{"min":6,"max":24,"mois":1},{"min":24,"max":null,"mois":2}],"EMPLOYE":[{"min":0,"max":6,"mois":1},{"min":6,"max":24,"mois":2},{"min":24,"max":null,"mois":2}],"AGENT_MAITRISE":[{"min":0,"max":24,"mois":2},{"min":24,"max":null,"mois":3}],"CADRE":[{"min":0,"max":null,"mois":3}]},"article":"CCN Travaux Publics Ouvriers (Tome II) art. 7"}', 'CCN Travaux Publics Ouvriers (IDCC 1702) — durée de préavis', 'FR', true, true, 'CCN Travaux Publics Tome II IDCC 1702 art. 7', 'Durée du préavis prévue par la convention collective des ouvriers des travaux publics (IDCC 1702, Tome II) selon la catégorie professionnelle et l''ancienneté en mois. Pattern aligné sur le bâtiment (IDCC 1597) : reproduit la durée légale L.1234-1 pour ouvriers/employés et un préavis cadre 3 mois dès l''embauche. Utilisé par F-DT-25 (calculateur indemnité compensatrice de préavis). Modifier la matrice si l''avenant CCN évolue.', NOW(), NULL);

INSERT INTO legal_referentials (id, workspace_id, legal_domain, referential_type, entry_key, value_json, label, country, is_system, is_active, source_ref, description, updated_at, updated_by)
